    if let Some(raw) = headers.get("authorization").and_then(|v| v.to_str().ok()) {
        let trimmed = raw.trim();
        if let Some(bearer) = trimmed.strip_prefix("Bearer ") {
            let token = bearer.trim();
            if !token.is_empty() {
                return Some(token.to_string());
            }
        }
    }

    None
}

