tokio::spawn(async move {
    tracing::info!("Starting unified gRPC server at {} (gRPC-Web enabled)", socket_addr);

    let reflection_service = tonic_reflection::server::Builder::configure()
        .register_encoded_file_descriptor_set(op_grpc_bridge::proto::FILE_DESCRIPTOR_SET)
        .build_v1()
        .unwrap();

    let mcp_service = McpServiceServer::new(mcp_grpc_service);
    let state_sync_service = StateSyncServer::new(op_grpc_server.clone());
    let plugin_service = PluginServiceServer::new(op_grpc_server.clone());
    let event_chain_service = EventChainServiceServer::new(op_grpc_server);

    // Wrap services with gRPC-Web support
    let mut server = tonic::transport::Server::builder()
        .accept_http1(true)
        .add_service(tonic_web::enable(reflection_service))
        .add_service(tonic_web::enable(state_sync_service))
        .add_service(tonic_web::enable(plugin_service))
        .add_service(tonic_web::enable(event_chain_service))
        .add_service(tonic_web::enable(mcp_service));

    if let Err(e) = server.serve(socket_addr).await {
