sudo python3 -c '
import sys
path = "/etc/nginx/http.d/dashboard-3tched.conf"
with open(path, "r") as f:
    content = f.read()

grpc_web_block = """
    # gRPC-Web Proxy to OVS Bridge
    location /operation. {
        proxy_pass http://10.88.88.1:50051;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_buffering off;
        proxy_read_timeout 3600s;
        send_timeout 3600s;

        # CORS headers for gRPC-Web
        add_header "Access-Control-Allow-Origin" "*" always;
        add_header "Access-Control-Allow-Methods" "GET, POST, OPTIONS" always;
        add_header "Access-Control-Allow-Headers" "keep-alive,user-agent,cache-control,content-type,content-transfer-encoding,x-accept-content-transfer-encoding,x-accept-response-streaming,x-user-agent,x-grpc-web,grpc-timeout" always;
        add_header "Access-Control-Expose-Headers" "grpc-status,grpc-message" always;

        if ($request_method = "OPTIONS") {
            return 204;
        }
    }
"""

# Insert before the API block
if "location /api/" in content:
    new_content = content.replace("    # API calls go to backend", grpc_web_block + "\n    # API calls go to backend")
    with open(path, "w") as f:
        f.write(new_content)
else:
    print("Could not find insertion point")
    sys.exit(1)
