import { useState } from "react";
import { PageHeader, Card, Pill } from "@/components/shell/Primitives";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Loader2, RefreshCcw, AlertCircle } from "lucide-react";

interface OpenClawModel {
  id: string;
  name: string;
  description?: string;
  available?: boolean;
  routing?: string;
}

export default function RoutableModelsPage() {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const { data, isLoading, error, refetch, isFetching } = useQuery({
    queryKey: ["openclaw-models"],
    queryFn: async () => {
      const resp = await api.openclaw.models();
      return resp.models as OpenClawModel[];
    },
  });

  const models = data || [];
  const selectedModel = models.find((m) => m.id === selectedId) || (models.length > 0 ? models[0] : null);

  if (isLoading) {
    return (
      <div className="flex h-full items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <>
      <PageHeader 
        title="Routable Models" 
        subtitle="LLM gateway model routing and configuration." 
        actions={
          <button 
            onClick={() => refetch()}
            disabled={isFetching}
            className="flex items-center gap-2 px-4 py-2 rounded-md border border-border bg-[hsl(var(--bg-elevated))] text-sm font-medium hover:bg-muted/30 transition-colors disabled:opacity-50"
          >
            <RefreshCcw className={`h-4 w-4 ${isFetching ? "animate-spin" : ""}`} />
            Refresh
          </button>
        } 
      />

      {error ? (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6 text-center">
          <AlertCircle className="h-10 w-10 text-destructive mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-destructive mb-2">Failed to load models</h3>
          <p className="text-muted-foreground mb-4">{(error as Error).message}</p>
          <button onClick={() => refetch()} className="text-primary hover:underline font-medium">Try again</button>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-4">
          {/* Model list */}
          <Card title="Available Routes">
            <div className="space-y-1 mt-2">
              {models.length === 0 ? (
                <div className="p-4 text-center text-sm text-muted-foreground italic">No models configured in OpenClaw.</div>
              ) : (
                models.map((m) => (
                  <button 
                    key={m.id} 
                    onClick={() => setSelectedId(m.id)}
                    className={`w-full text-left p-3 rounded-lg border transition-colors ${
                      (selectedId === m.id || (!selectedId && m === selectedModel)) 
                        ? "border-primary/30 bg-primary/5" 
                        : "border-transparent hover:bg-muted/30"
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-medium text-foreground truncate">{m.name}</div>
                        <div className="text-[11px] text-muted-foreground font-mono truncate">{m.id}</div>
                      </div>
                      <Pill variant={m.available ? "ok" : "default"}>{m.available ? "Available" : "Offline"}</Pill>
                    </div>
                  </button>
                ))
              )}
            </div>
          </Card>

          {/* Model detail */}
          {selectedModel ? (
            <div className="space-y-4">
              <Card>
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <div className="text-xl font-bold text-foreground">{selectedModel.name}</div>
                    <div className="text-sm text-muted-foreground font-mono mt-1">{selectedModel.id}</div>
                  </div>
                  <Pill variant={selectedModel.available ? "ok" : "default"} className="text-xs">
                    {selectedModel.available ? "ACTIVE ROUTE" : "INACTIVE"}
                  </Pill>
                </div>

                <div className="space-y-4">
                  <div>
                    <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">Description</h4>
                    <p className="text-sm text-foreground leading-relaxed">
                      {selectedModel.description || "No description provided for this route."}
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Routing Strategy</h4>
                      <div className="text-sm font-medium">{selectedModel.routing || "agent-default"}</div>
                    </div>
                    <div>
                      <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Provider</h4>
                      <div className="text-sm font-medium">OpenClaw Gateway</div>
                    </div>
                  </div>
                </div>
              </Card>

              <Card title="Route Configuration">
                <div className="p-4 border rounded-md bg-muted/10">
                  <div className="text-sm text-muted-foreground italic mb-2">
                    OpenClaw routes are managed via the gateway configuration. 
                    Target agent and model stack are dynamically selected based on this route key.
                  </div>
                  <div className="flex justify-end">
                    <button className="text-xs font-medium text-primary hover:underline">View Gateway Config</button>
                  </div>
                </div>
              </Card>
            </div>
          ) : (
            <div className="flex h-full items-center justify-center border rounded-xl border-dashed border-border p-12">
              <div className="text-center">
                <AlertCircle className="h-8 w-8 text-muted-foreground mx-auto mb-2 opacity-50" />
                <div className="text-muted-foreground">Select a route to view details</div>
              </div>
            </div>
          )}
        </div>
      )}
    </>
  );
}

