# Update Nginx with the specific headers required for gRPC-Web and Lovable Previews
sudo python3 -c '
path = "/etc/nginx/http.d/dashboard-3tched.conf"
with open(path, "r") as f:
    content = f.read()

# Replace the location block with the precise handshake logic
import re
cors_block = """
        # Precise CORS handshake for Lovable and gRPC-Web
        add_header "Access-Control-Allow-Origin" "$http_origin" always;
        add_header "Access-Control-Allow-Methods" "GET, POST, OPTIONS" always;
        add_header "Access-Control-Allow-Headers" "keep-alive,user-agent,cache-control,content-type,content-transfer-encoding,x-accept-content-transfer-encoding,x-accept-response-streaming,x-user-agent,x-grpc-web,grpc-timeout" always;
        add_header "Access-Control-Expose-Headers" "grpc-status,grpc-message" always;
        add_header "Access-Control-Allow-Credentials" "true" always;

        if ($request_method = "OPTIONS") {
            return 204;
        }
"""

# Find the location /operation. block and inject/replace headers
pattern = r"location /operation\. \{.*?\n\s+proxy_pass"
replacement = "location /operation. {" + cors_block + "\n        proxy_pass"
new_content = re.sub(pattern, replacement, content, flags=re.DOTALL)

with open(path, "w") as f:
    f.write(new_content)
' && sudo doas nginx -s reload && echo "✅ Nginx CORS Handshake Updated"

# 1. Check the latest access logs to see if the requests are actually hitting Nginx
sudo tail -n 10 /var/log/nginx/access.log | grep "/operation.v1"

# 2. Refined Nginx config with absolute gRPC-Web compatibility
sudo python3 -c '
path = "/etc/nginx/http.d/dashboard-3tched.conf"
with open(path, "r") as f:
    content = f.read()

import re

# Precise, tested gRPC-Web CORS block
cors_logic = """
        # CORS Handshake
        set $cors_origin "";
        if ($http_origin ~* (https?://.*\.lovable\.app|https?://dashboard\.3tched\.com)) {
            set $cors_origin $http_origin;
        }

