# 1. Add PluginDbusHost to crates/op-state/src/dbus_server.rs
# This allows any StatePlugin to be exported as a D-Bus object.

cat >> crates/op-state/src/dbus_server.rs <<EOF

/// D-Bus interface for an individual plugin
pub struct PluginDbusHost {
    pub plugin: Arc<RwLock<dyn StatePlugin>>,
}

#[zbus::interface(name = "org.opdbus.PluginV1")]
impl PluginDbusHost {
    #[zbus(property)]
    async fn name(&self) -> String {
        self.plugin.read().await.name().to_string()
    }

    #[zbus(property)]
    async fn version(&self) -> String {
        self.plugin.read().await.version().to_string()
    }

    #[zbus(property)]
    async fn description(&self) -> String {
        self.plugin.read().await.description().to_string()
    }

    /// Get current state as JSON
    async fn get_state(&self) -> zbus::fdo::Result<String> {
        let state = self.plugin.read().await.get_state().await
            .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))?;
        Ok(simd_json::to_string(&state).unwrap_or_default())
    }

    /// Get schema as JSON
    async fn get_schema(&self) -> zbus::fdo::Result<String> {
        let metadata = self.plugin.read().await.metadata();
        // Return the first object schema as primary
        let schema = metadata.object_schemas.values().next().cloned().unwrap_or(simd_json::json!({}));
        Ok(simd_json::to_string(&schema).unwrap_or_default())
    }
}
EOF

