/// Core plugin trait and types

use anyhow::Result;
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use simd_json::ValueBuilder;
use std::any::Any;
use std::collections::HashMap;
use std::path::PathBuf;

use crate::state::{DesiredState, StateChange, ValidationResult};
use op_core::state_publisher::StatePublisher;
pub use op_state::plugin::PluginMetadata;

/// Context provided to plugin during initialization
#[derive(Debug, Clone)]
pub struct PluginContext {
    /// Optional state publisher for authoritative updates
    pub publisher: Option<std::sync::Arc<dyn StatePublisher>>,
    /// Dedicated BTRFS subvolume path for this plugin's storage
    pub storage_path: PathBuf,
    /// Assigned NUMA node (if available)
    pub numa_node: Option<u32>,
    /// Plugin configuration
    pub config: Value,
}

impl Default for PluginContext {
    fn default() -> Self {
        Self {
            publisher: None,
            storage_path: PathBuf::from("/var/lib/op-dbus/plugins/default"),
            numa_node: None,
            config: Value::null(),
        }
    }
}

/// Plugin tunable parameters (runtime configuration)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginTunables {
    pub priority: i32,
    pub max_retries: u32,
    pub timeout_ms: u64,
    pub enabled: bool,
    #[serde(default)]
    pub config: Value,
}

impl Default for PluginTunables {
    fn default() -> Self {
        Self {
            priority: 0,
            max_retries: 3,
            timeout_ms: 30000,
            enabled: true,
            config: Value::null(),
        }
    }
}

/// Plugin capabilities
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginCapabilities {
    pub can_read: bool,
    pub can_write: bool,
    pub can_delete: bool,
    pub supports_dry_run: bool,
    pub supports_rollback: bool,
    pub supports_transactions: bool,
    pub requires_root: bool,
    pub supported_platforms: Vec<String>,
}

impl Default for PluginCapabilities {
    fn default() -> Self {
        Self {
            can_read: true,
            can_write: true,
            can_delete: false,
            supports_dry_run: true,
            supports_rollback: false,
            supports_transactions: false,
            requires_root: false,
            supported_platforms: vec!["linux".to_string()],
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FeatureSchema {
    pub feature_type: String,
    pub version: String,
    pub config: Value,
    /// Capability tags (e.g. "immutable", "core", "optional")
    #[serde(default)]
    pub tags: Vec<String>,
    /// Specific JSON configuration paths that are immutable (e.g. ["/metadata/id"])
    #[serde(default)]
    pub immutable_paths: Vec<String>,
}

impl FeatureSchema {
    pub fn is_fully_immutable(&self) -> bool {
        self.tags.iter().any(|t| t == "immutable")
    }

    pub fn is_path_immutable(&self, path: &str) -> bool {
        self.is_fully_immutable() || self.immutable_paths.iter().any(|p| p == path)
    }
}

/// Core plugin trait that all plugins must implement
#[async_trait]
pub trait Plugin: Send + Sync {
    /// Unique name for this plugin
    fn name(&self) -> &str;

    /// Description of what this plugin does
    fn description(&self) -> &str;

    /// Version of the plugin
    fn version(&self) -> &str;

    /// Get the current state managed by this plugin
    async fn get_state(&self) -> Result<Value>;

    /// Get the desired state (target configuration)
    async fn get_desired_state(&self) -> Result<DesiredState>;

    /// Set the desired state
    async fn set_desired_state(&self, desired: DesiredState) -> Result<()>;

    /// Apply the desired state (reconcile current -> desired)
    async fn apply_state(&self) -> Result<Vec<StateChange>>;

    /// Calculate diff between current and desired state
    async fn diff(&self) -> Result<Vec<StateChange>>;

    /// Validate a configuration before applying
    async fn validate(&self, config: &Value) -> Result<ValidationResult>;

    /// Get plugin capabilities
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities::default()
    }

    /// Get plugin metadata
    fn metadata(&self) -> PluginMetadata {
        PluginMetadata {
            name: self.name().to_string(),
            version: self.version().to_string(),
            description: self.description().to_string(),
            object_schemas: HashMap::new(),
        }
    }

    /// Handle plugin-specific commands
    async fn handle_command(&self, command: &str, _args: Value) -> Result<Value> {
        Err(anyhow::anyhow!(
            "Command '{}' not supported by plugin '{}'",
            command,
            self.name()
        ))
    }

    /// Initialize the plugin with context
    async fn initialize(&mut self, _context: PluginContext) -> Result<()> {
        Ok(())
    }

    /// Cleanup when plugin is being removed
    async fn cleanup(&mut self) -> Result<()> {
        Ok(())
    }

    /// Get hash of current state for blockchain footprint
    fn state_hash(&self) -> String {
        use sha2::{Digest, Sha256};
        // Default implementation - plugins should override for accuracy
        let mut hasher = Sha256::new();
        hasher.update(self.name().as_bytes());
        hasher.update(self.version().as_bytes());
        format!("{:x}", hasher.finalize())
    }

    /// Convert to Any for downcasting
    fn as_any(&self) -> &dyn Any;
}

/// Boxed plugin type
pub type BoxedPlugin = Box<dyn Plugin>;

//! Plugin Registry - Sole Authoritative Source for State
//!
//! Provides a durable, NUMA-aware, BTRFS-integrated registry for all plugins.

use anyhow::{anyhow, Result};
use op_core::state_publisher::StatePublisher;
use op_state::StatePlugin;
use op_state_store::{PluginSchema, SchemaRegistry};
use simd_json::OwnedValue as Value;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::process::Command;
use tokio::sync::RwLock;
use tracing::{info, warn};

/// Registry record for a plugin
pub struct PluginRecord {
    pub name: String,
    pub plugin: Arc<RwLock<dyn StatePlugin>>,
    pub storage_path: PathBuf,
    pub change_count: u64,
    pub schema: Option<PluginSchema>,
    pub dbus_path: String,
}

/// Sole authoritative plugin registry
pub struct PluginRegistry {
    plugins: Arc<RwLock<HashMap<String, PluginRecord>>>,
    schema_registry: Arc<RwLock<SchemaRegistry>>,
    base_path: PathBuf,
    publisher: RwLock<Option<Arc<dyn StatePublisher>>>,
    dbus_conn: RwLock<Option<zbus::Connection>>,
}

impl PluginRegistry {
    /// Create a new authoritative registry
    pub fn new(base_path: impl AsRef<Path>, schema_registry: Arc<RwLock<SchemaRegistry>>) -> Self {
        Self {
            plugins: Arc::new(RwLock::new(HashMap::new())),
            schema_registry,
            base_path: base_path.as_ref().to_path_buf(),
            publisher: RwLock::new(None),
            dbus_conn: RwLock::new(None),
        }
    }

    /// Set the state publisher for authoritative updates
    pub async fn set_publisher(&self, publisher: Arc<dyn StatePublisher>) {
        *self.publisher.write().await = Some(publisher);
    }

    /// Set the D-Bus connection for object exportation
    pub async fn set_dbus_connection(&self, conn: zbus::Connection) {
        *self.dbus_conn.write().await = Some(conn);
    }

    /// Register a plugin instance
    pub async fn register(&self, name: String, plugin: Arc<RwLock<dyn StatePlugin>>) -> Result<()> {
        let mut plugins = self.plugins.write().await;

        if plugins.contains_key(&name) {
            return Err(anyhow!("Plugin '{}' already registered", name));
        }

        // Ensure BTRFS subvolume for plugin storage
        let storage_path = self.create_plugin_subvolume(&name).await?;

        let dbus_path_str = format!("/org/opdbus/v1/plugins/{}", name);

        // Export to D-Bus if connection is available
        if let Some(conn) = &*self.dbus_conn.read().await {
            let host = op_state::dbus_server::PluginDbusHost {
                plugin: plugin.clone(),
            };
            if let Ok(path) = zbus::zvariant::ObjectPath::try_from(dbus_path_str.as_str()) {
                let _ = conn.object_server().at(path, host).await;
                info!("Plugin {} exported to D-Bus at {}", name, dbus_path_str);
            }
        }

        // Extract schema from plugin
        let schema = plugin.read().await.schema();

        // Register schema in SchemaRegistry
        if let Some(s) = &schema {
            self.schema_registry.write().await.register(s.clone());
            info!("Plugin {} schema registered in SchemaRegistry", name);

            // Project schema to SyncEngine immediately so UI can build forms
            if let Some(publ) = &*self.publisher.read().await {
                let _ = publ
                    .publish_change(
                        name.clone(),
                        format!("schema/{}", name),
                        op_core::state_publisher::ChangeType::PropertySet,
                        Some("definition".to_string()),
                        None,
                        s.to_json_schema(),
                        vec!["schema".to_string()],
                        "registry".to_string(),
                    )
                    .await;
                info!("Plugin {} schema projected to SyncEngine", name);
            }
        }

        plugins.insert(
            name.clone(),
            PluginRecord {
                name,
                plugin,
                storage_path,
                change_count: 0,
                schema,
                dbus_path: dbus_path_str,
            },
        );

        Ok(())
    }

    /// Get a plugin by name
    pub async fn get(&self, name: &str) -> Option<Arc<RwLock<dyn StatePlugin>>> {
        let plugins = self.plugins.read().await;
        plugins.get(name).map(|r| r.plugin.clone())
    }

    async fn create_plugin_subvolume(&self, name: &str) -> Result<PathBuf> {
        let path = self.base_path.join("plugins").join(name);

        if path.exists() {
            return Ok(path);
        }

        tokio::fs::create_dir_all(path.parent().unwrap()).await?;

        let output = Command::new("btrfs")
            .args(["subvolume", "create"])
            .arg(&path)
            .output()
            .await?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.contains("not a btrfs filesystem") {
                warn!(
                    "BTRFS subvolume creation failed: {}. Falling back to directory.",
                    stderr
                );
            }
            tokio::fs::create_dir_all(&path).await?;
        }

        Ok(path)
    }
}

